<?php
declare(strict_types=1);
require __DIR__.'/app/bootstrap.php';require __DIR__.'/app/customer.php';require_customer();$a=current_customer();$id=(int)($_GET['id']??0);
$q=db()->prepare('SELECT * FROM plaques WHERE id=? AND company_id=? LIMIT 1');$q->execute([$id,$a['company_id']]);$p=$q->fetch();if(!$p){http_response_code(404);exit('Placa não encontrada.');}
$companyQ=db()->prepare('SELECT * FROM companies WHERE id=?');$companyQ->execute([$a['company_id']]);$company=$companyQ->fetch();$prq=db()->prepare("SELECT id,name FROM projects WHERE status='active' AND (company_id=? OR company_id IS NULL) ORDER BY name");$prq->execute([$a['company_id']]);$projects=$prq->fetchAll();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{[$type,$url,$phone,$message]=customer_company_destination($_POST);$project=(int)($_POST['project_id']??0)?:null;$q=db()->prepare('UPDATE plaques SET product_type=?,destination_url=?,whatsapp_phone=?,whatsapp_message=?,instagram_url=?,project_id=? WHERE id=? AND company_id=?');$q->execute([$type,$url,$phone,$message,$type==='instagram'?$url:null,$project,$id,$a['company_id']]);flash('Destino e tipo de produto atualizados. O QR e o NFC não precisam ser regravados.');header('Location: customer-plaque.php?id='.$id);exit;}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Não foi possível salvar.';}}
layout_start('Configurar placa');
?><div class="heading"><div><h1>Configurar <?=e($p['code'])?></h1><p>Altere o destino sem trocar o QR Code ou o NFC.</p></div><a class="button secondary" href="customer-dashboard.php">Voltar</a></div><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><form method="post" class="panel"><?=client_csrf_field()?><label>Tipo de placa<select name="product_type" id="product-type"><option value="google_review" <?=$p['product_type']==='google_review'?'selected':''?>>Avaliações Google</option><option value="whatsapp" <?=$p['product_type']==='whatsapp'?'selected':''?>>WhatsApp</option><option value="instagram" <?=$p['product_type']==='instagram'?'selected':''?>>Instagram</option></select></label><label class="dest-google">Link de avaliação Google<input type="url" name="destination_url" value="<?=e($p['product_type']==='google_review'?($p['destination_url']?:($company['google_review_url']??'')):'')?>"></label><label class="dest-whatsapp">WhatsApp com DDI e DDD<input name="whatsapp_phone" placeholder="5521999999999" value="<?=e($p['whatsapp_phone']??'')?>"></label><label class="dest-whatsapp">Mensagem inicial (opcional)<input name="whatsapp_message" maxlength="500" value="<?=e($p['whatsapp_message']??'')?>"></label><label class="dest-instagram">Link do Instagram<input type="url" name="instagram_url" value="<?=e($p['product_type']==='instagram'?$p['destination_url']:'')?>"></label><label>Projeto<select name="project_id"><option value="">Sem projeto</option><?php foreach($projects as $pr):?><option value="<?=$pr['id']?>" <?=$p['project_id']==$pr['id']?'selected':''?>><?=e($pr['name'])?></option><?php endforeach;?></select></label><button>Salvar destino</button></form><script>
(function(){const s=document.getElementById('product-type');function update(){document.querySelectorAll('.dest-google,.dest-whatsapp,.dest-instagram').forEach(e=>e.style.display='none');document.querySelectorAll(s.value==='google_review'?'.dest-google':s.value==='whatsapp'?'.dest-whatsapp':'.dest-instagram').forEach(e=>e.style.display='block');}s.addEventListener('change',update);update();})();
</script><?php layout_end(); ?>